const repository = "madfanat/ITMOv2";
const scheduled = Boolean($input.first().json.timestamp);
const now = $now.setZone('Europe/Moscow');
const monday = now.startOf('week').set({hour: 9});
const scheduledEnd = monday > now ? monday.minus({weeks: 1}) : monday;
const end = (scheduled ? scheduledEnd : now).startOf('second');
const start = end.minus({weeks: 1});
const mode = scheduled ? 'scheduled' : 'manual';
const key = date => [repository, mode, date.toISODate()].join('|');
return [{ json: {
  repository,
  weekKey: key(end), previousWeekKey: key(start),
  start: start.toUTC().toISO({suppressMilliseconds:true}),
  end: end.toUTC().toISO({suppressMilliseconds:true}),
  lastSecond: end.minus({seconds:1}).toUTC().toISO({suppressMilliseconds:true}),
} }];

const window = $('Set report window').first().json;
const within = value => typeof value === 'string' && value >= window.start && value < window.end;
const search = name => {
  const pages = $(name).all().map(item => item.json);
  if (pages.some(page => page.incomplete_results || !Array.isArray(page.items))) {
    throw new Error(name + ': incomplete GitHub search');
  }
  const byId = new Map(pages.flatMap(page => page.items).map(row => [row.id, row]));
  if (byId.size !== pages[0].total_count) {
    throw new Error(name + ': GitHub result count differs from fetched rows');
  }
  return [...byId.values()];
};
const types = ['bug', 'task', 'feature', 'needs-triage', 'unclassified'];
const byType = Object.fromEntries(types.map(type => [type, 0]));
const byAuthor = new Map();
const opened = search('Opened Issues').filter(issue => !issue.pull_request && within(issue.created_at));
for (const issue of opened) {
  const labels = new Set(issue.labels.map(label => label.name));
  const classified = types.slice(0, 3).filter(type => labels.has(type));
  const type = labels.has('needs-triage') ? 'needs-triage' : classified.length === 1 ? classified[0] : 'unclassified';
  byType[type]++;
  const login = issue.user?.login ?? '(удалённый пользователь)';
  const author = byAuthor.get(login) ?? { total: 0, byType: Object.fromEntries(types.map(type => [type, 0])) };
  author.total++;
  author.byType[type]++;
  byAuthor.set(login, author);
}
const closed = search('Closed Issues').filter(issue => !issue.pull_request && within(issue.closed_at)).length;
const merged = search('Merged pull requests').filter(pr => pr.pull_request && within(pr.pull_request.merged_at)).length;
const comments = new Set($input.all().map(item => item.json)
  .filter(comment => within(comment.created_at) && /\/issues\/\d+(?:[?#]|$)/.test(comment.html_url ?? ''))
  .map(comment => comment.id)).size;
return [{ json: { ...window, stats: {
  activity: { opened: opened.length, closed, comments, merged },
  byType,
  byAuthor: Object.fromEntries([...byAuthor].sort(([a], [b]) => a.localeCompare(b))),
} } }];

const current = $('Group by type and author').first().json;
const row = $input.first().json;
const previous = row.stats_json ? JSON.parse(row.stats_json) : null;
const difference = (today, before) => Object.fromEntries(
  [...new Set([...Object.keys(today), ...Object.keys(before)])]
    .map(key => [key, (Object.hasOwn(today, key) ? today[key] : 0) - (Object.hasOwn(before, key) ? before[key] : 0)])
);
const totals = rows => Object.fromEntries(Object.entries(rows).map(([name, entry]) => [name, entry.total]));
const delta = previous ? {
  activity: difference(current.stats.activity, previous.activity),
  byType: difference(current.stats.byType, previous.byType),
  byAuthor: difference(totals(current.stats.byAuthor), totals(previous.byAuthor)),
} : null;
const counts = Object.entries(current.stats.byType);
const highest = Math.max(0, ...counts.map(([, count]) => count));
const mostFrequentTypes = highest > 0 ? counts.filter(([, count]) => count === highest).map(([type]) => type) : [];
return [{ json: { ...current, previousSource: row.source ?? null, delta, mostFrequentTypes } }];

const report = $('Calculate weekly difference').first().json;
const annotation = $input.first().json.text?.trim();
if (!annotation) throw new Error('The weekly AI annotation is empty');
const escape = value => String(value).replace(/[&<>"']/g, char => ({
  '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;',
})[char]);
const cell = (tag, value) => `<${tag} style="padding:6px 10px;border:1px solid #d0d7de;text-align:left">${escape(value)}</${tag}>`;
const table = (title, headers, rows) => `<h2>${escape(title)}</h2><table style="border-collapse:collapse"><thead><tr>${headers.map(x => cell('th', x)).join('')}</tr></thead><tbody>${rows.map(row => '<tr>' + row.map(x => cell('td', x)).join('') + '</tr>').join('')}</tbody></table>`;
const signed = value => typeof value !== 'number' ? '—' : value > 0 ? '+' + value : String(value);
const activity = { opened:'Открыто Issues', closed:'Закрыто Issues', comments:'Комментариев в Issues', merged:'Смержено PR' };
const types = Object.keys(report.stats.byType);
const authorNames = [...new Set([...Object.keys(report.stats.byAuthor), ...Object.keys(report.delta?.byAuthor ?? {})])].sort();
const authorRows = authorNames.map(name => {
  const entry = Object.hasOwn(report.stats.byAuthor, name) ? report.stats.byAuthor[name] : null;
  return [name, ...types.map(type => entry?.byType[type] ?? 0), entry?.total ?? 0, signed(report.delta?.byAuthor[name])];
});
const note = report.previousSource === 'fixture' ? 'Предыдущая неделя — тестовая запись для демонстрации.'
  : report.delta ? 'Δ показывает изменение к предыдущей неделе.' : 'За предыдущую неделю снимка нет.';
const title = `Недельная статистика Issues · ${report.repository}`;
const html = `<!doctype html><html lang="ru"><body style="font:15px Arial,sans-serif;color:#24292f"><h1>${escape(title)}</h1>
<p>Период: ${escape(report.start)} — ${escape(report.end)} (UTC, конец интервала исключён).</p>
<p>${escape(note)}</p>
${table('Активность', ['Метрика','За неделю','Δ'], Object.entries(activity).map(([key,name]) => [name, report.stats.activity[key], signed(report.delta?.activity[key])]))}
${table('Новые Issues по типам', ['Тип','За неделю','Δ'], types.map(type => [type, report.stats.byType[type], signed(report.delta?.byType[type])]))}
${table('Новые Issues по авторам', ['Автор',...types,'Всего','Δ всего'], authorRows.length ? authorRows : [['Нет новых Issues', ...types.map(() => 0), 0, '—']])}
<h2>AI-комментарий недели</h2><p>${escape(annotation)}</p></body></html>`;
return [{ json: { subject: title + ' · ' + report.weekKey.split('|').at(-1), html, annotation } }];
